_AGE = re.compile(r"^(\d+(?:\.\d+)?)\s*([smhd])$")


def parse_age(v: str | int | float | None) -> float | None:
    if v is None:
        return None
    if isinstance(v, (int, float)):
        return float(v)
    m = _AGE.match(v.strip())
    if not m:
        raise UsageError(f"bad max_age {v!r}; use e.g. 24h, 30m, 2d")
    return float(m.group(1)) * {"s": 1, "m": 60, "h": 3600, "d": 86400}[m.group(2)]


